package studio.jiayu.neoagent;
import android.content.*;import org.json.*;import java.io.*;
public class InspectReceiver extends BroadcastReceiver {
 public void onReceive(Context ctx,Intent intent){try{ControlService s=ControlService.instance;JSONObject o=new JSONObject().put("request_id",java.util.UUID.randomUUID().toString()).put("sampledAt",System.currentTimeMillis()).put("connected",s!=null&&s.connected).put("running",s!=null&&s.running).put("paused",s!=null&&s.paused);if(s!=null){o.put("agent_ime",s.agentImeLease.status()).put("monitor",s.runtimeHealth.snapshot()).put("modelCalls",s.modelCalls).put("actions",s.actions);android.view.accessibility.AccessibilityNodeInfo root=s.getRootInActiveWindow();boolean expected=root!=null&&s.allowed.contentEquals(root.getPackageName());o.put("expectedForeground",expected);if(expected){android.graphics.Rect box=new android.graphics.Rect();root.getBoundsInScreen(box);o.put("root_bounds",new JSONArray().put(box.left).put(box.top).put(box.right).put(box.bottom)).put("root_visible",root.isVisibleToUser()).put("root_children",root.getChildCount());NativeWindowState state=NativeWindowState.inspect(s);o.put("window_bounds",new JSONArray().put(state.bounds.left).put(state.bounds.top).put(state.bounds.right).put(state.bounds.bottom));}if(expected&&s.allowed.equals("tv.danmaku.bili"))o.put("test_target_visible",!root.findAccessibilityNodeInfosByText("航拍中国").isEmpty()).put("playback_label_visible",!root.findAccessibilityNodeInfosByText("播放").isEmpty()).put("search_results_tabs",!root.findAccessibilityNodeInfosByText("综合").isEmpty());if(expected&&s.allowed.equals("com.taobao.taobao"))o.put("test_target_visible",!root.findAccessibilityNodeInfosByText("Neo").isEmpty()||!root.findAccessibilityNodeInfosByText("neo").isEmpty());}try(FileOutputStream out=ctx.openFileOutput("qa-native-tree.json",0)){out.write(o.toString().getBytes("UTF-8"));}}catch(Exception ignored){}}
}
